      (["On sécurise la personne.","On fait évaluer par un professionnel de santé mentale.","On décide du lieu de soins le moins restrictif."],[("d'abord","médecin de premier recours","Il demande sans détour idées, scénario et moyens, et ne laisse pas seule une personne qui a un plan."),("en même temps","psychiatre de garde","Il évalue dans les 24 heures, sans échelle décisionnelle, et formule le risque avec la personne."),("ensuite","équipe de crise","Elle retire les moyens, associe les proches avec l'accord de la personne et choisit domicile, structure intermédiaire, hospitalisation ou placement.")]),
      (["On suit de près après la crise.","On traite un trouble sous-jacent."],[("d'abord","médecin de famille","Il revoit la personne dans les 48 heures si des inquiétudes persistent."),("ensuite","psychiatre ou psychologue","Il poursuit la psychothérapie et traite un épisode dépressif caractérisé."),("puis","équipe de suivi","Elle maintient des contacts réguliers et révise le plan de sécurité avec la personne et ses proches.")]),
